use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let lineup = stable.herd.lineup();
    var entries: List<String> = [];
    var i = 0;
    while i < lineup.len() {
        match lineup.get(index: i) {
            Some(pony) => {
                let fed = stable.herd.feed(pony: pony, scoops: 3);
                let entry = stable.ledger.entry(fed);
                entries.push(item: entry);
            },
            None => {}
        }
        i = i + 1;
    }
    let result = entries.join(sep: ",");
    io.write(text: result)?;
    return Ok(unit);
}

use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var i = 0;
    while i < frames.len() {
        let frame = match frames.get(index: i) {
            Some(f) => f,
            None => break,
        };
        let value = match relay.feed.decode(frame) {
            Ok(v) => v,
            _ => 0,
        };
        total = total + value;
        i = i + 1;
    }
    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

