use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = mill.stock.planks();
    var kept: List<String> = [];
    var i = 0;
    let len = planks.len();
    while i < len {
        match planks.get(i) {
            Some(p) => {
                if mill.rules.is_kept(p) {
                    kept.push(mill.rules.to_label(p));
                }
            }
            None => {}
        }
        i = i + 1;
    }
    return kept.join(sep: ",");
}

